			/**
			 * 
			 * @param {cpr.controls.Grid} grdList
			 * @param {Number} colIdx
			 * @param {any} colNm
			 */
			function _addCol(grdList, colIdx, colNm){
			    console.log(colNm);
			    grdList.addColumn({
			        // 1. 추가 컬럼의 width
			        columnLayout: [{
			            width: "100px"
			        }],
			        // 2. 추가 컬럼의 header정보
			        // - rowIndex는 헤더 컬럼의 로우 인덱스이며 한줄일경우에 0
			        // - colIndex는 0부터 시작 순번컬럼과 기본컬럼이 있으므로 +2부터 시작
			        // - configurator.text는 그리드 헤더에 표현될 label 입니다.
			        header: [{
			            constraint: {
			                rowIndex: 0,
			//                colIndex: rowIdx,
			                colIndex: colIdx,
			                colSpan: 1,
			                rowSpan: 1
			            },
			            configurator: function(configurator) {
			                if (colNm == "SSUM") {
			                    configurator.text = '합 계';
			                } else {
			                    configurator.text = colNm.substr(1,4)+"-"+colNm.substr(5,2);
			                } 
			            }
			        }],
			        // 3. 추가 컬럼의 detail 정보
			        // - configurator.columnName는 그리드에 바인딩될 데이터 셋의 컬럼명입니다.
			        detail: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: colIdx,
			                colSpan: 1,
			                rowSpan: 1
			            },
			            configurator: function(configurator) {
			                configurator.columnName = colNm;
			                configurator.control = (function(){
			                    var numberEditor_1 = new cpr.controls.NumberEditor("nbe1");
			                    numberEditor_1.spinButton = false;
			                    numberEditor_1.bind("value").toDataColumn(colNm);
			                    return numberEditor_1;
			                })();
			                configurator.controlConstraint = {};
			            }
			        }],
			        footer: [{
			            constraint: { 
			                rowIndex: 0, 
			                colIndex: colIdx, 
			                colSpan: 1, 
			                rowSpan: 1
			            },
			            configurator: function (configurator) {
			                
			                    configurator.expr = "getSum('" + colNm + "')";
			                    configurator.control = (function(){
			                        var numberEditor_1 = new cpr.controls.NumberEditor("nbe1");
			                        numberEditor_1.spinButton = false;
			                        numberEditor_1.format = "s#,##0";
			                        return numberEditor_1;

			//                        var output = new cpr.controls.Output(colNm);
			//                        output.dataType = "number";
			//                        output.formt = "s#,##0";
			//                        output.style.css({
			//                            "text-align" : "right"
			//                        });
			//                        return output;
			                        
			                    })();
			                    configurator.controlConstraint = {};
			            }
			        }]
			    });        
			}

